-- ============================================================================
-- Coffee Game Satarkhan - Complete Local QA / Demo Dataset
-- Target schema: uploaded coffee_game_satarkhan (MySQL 9.1)
-- Data only: this file does NOT create or alter tables.
-- Safe to rerun: it resets only records whose slug/type/email is prefixed DEMO.
--
-- Shared password for every demo account: Demo@12345
-- Main login: demo.admin@coffee.local / Demo@12345
-- ============================================================================

SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET @demo_now = NOW();
START TRANSACTION;

