SET @t_published = (SELECT id FROM tournaments WHERE slug='demo-qa-published' LIMIT 1);

-- Remove prior child rows belonging only to these demo tournaments
DELETE FROM tournament_matches WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM tournament_rounds WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM tournament_participant_state WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM waitlist_entries WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM registration_holds WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM registrations WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM discounts WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM tournament_sponsors WHERE tournament_id IN (@t_open,@t_seed,@t_manual,@t_group,@t_swiss,@t_double,@t_running,@t_team,@t_completed,@t_draft,@t_published);
DELETE FROM audit_logs WHERE action LIKE 'demo.%';
DELETE FROM notifications WHERE type LIKE 'demo_%';
DELETE re FROM ranking_entries re JOIN players p ON p.id=re.player_id JOIN users u ON u.id=p.user_id WHERE u.email LIKE 'demo.player%@coffee.local';

