-- --------------------------------------------------------------------------
-- Verification output
-- --------------------------------------------------------------------------
SELECT 'DEMO_DATA_READY' AS status, DATABASE() AS database_name, NOW() AS completed_at;
SELECT email,mobile,'Demo@12345' AS password FROM users WHERE email LIKE 'demo.%@coffee.local' ORDER BY email;
SELECT status,COUNT(*) AS tournaments FROM tournaments WHERE slug LIKE 'demo-qa-%' GROUP BY status ORDER BY status;
SELECT t.title,COUNT(DISTINCT r.id) AS registrations,COUNT(DISTINCT m.id) AS matches FROM tournaments t LEFT JOIN registrations r ON r.tournament_id=t.id LEFT JOIN tournament_matches m ON m.tournament_id=t.id WHERE t.slug LIKE 'demo-qa-%' GROUP BY t.id,t.title ORDER BY t.id;
