INSERT INTO user_roles(user_id,role_id) SELECT u.id,r.id FROM users u CROSS JOIN roles r WHERE u.email LIKE 'demo.player%@coffee.local' AND r.name='player';
INSERT INTO players(user_id,name,mobile,avatar_url,is_guest,created_at,updated_at) SELECT id,name,mobile,NULL,0,NOW(),NOW() FROM users WHERE email LIKE 'demo.player%@coffee.local' ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),name=VALUES(name),mobile=VALUES(mobile),is_guest=0,updated_at=NOW();
