i_slot=VALUES(allow_multi_slot),has_third_place=VALUES(has_third_place),draw_mode=VALUES(draw_mode),rules=VALUES(rules),game_settings=VALUES(game_settings),scoring_settings=VALUES(scoring_settings),prize_settings=VALUES(prize_settings),is_featured=VALUES(is_featured),published_at=VALUES(published_at),deleted_at=NULL,updated_at=NOW();
