INSERT INTO notifications(user_id,type,title,body,data,read_at,created_at) VALUES(@u01,'demo_registration_confirmed','ثبت‌نام نمونه تأیید شد','ثبت‌نام شما در مسابقه دمو تأیید شده است.',JSON_OBJECT('tournamentId',@t_open),NULL,NOW()),(@u03,'demo_payment_correction','اصلاح پرداخت نمونه','اطلاعات پرداخت نیاز به اصلاح دارد.',JSON_OBJECT('tournamentId',@t_open),NULL,NOW()),(@u09,'demo_waitlist','عضویت در صف انتظار','شما در موقعیت اول صف انتظار قرار دارید.',JSON_OBJECT('tournamentId',@t_open),NULL,NOW()),(@u10,'demo_waitlist_offer','ظرفیت برای شما آزاد شد','پیشنهاد ظرفیت تا ۳۰ دقیقه معتبر است.',JSON_OBJECT('tournamentId',@t_open),NULL,NOW()),(@u17,'demo_team_invitation','دعوت به تیم آلفا','کاپیتان تیم آلفا شما را دعوت کرده است.',JSON_OBJECT('teamId',@team_alpha),NULL,NOW()),(@u_admin,'demo_admin_payment','پرداخت نمونه نیازمند بررسی','یک پرداخت کارت‌به‌کارت در صندوق قرار دارد.',JSON_OBJECT('tournamentId',@t_open),NULL,NOW()),(@u_referee,'demo_referee_match','بازی نمونه به شما تخصیص یافت','یک بازی زنده و یک بازی آماده برای داوری دارید.',JSON_OBJECT('tournamentId',@t_running),NULL,NOW());
